using System;using System.Linq;
namespace IdleIntelligence.Core
{
 public sealed class AdvanceOutcome{public GameState State;public AdvanceCapture Report;}
 public sealed class AdvanceCapture
 {
  public long[] Components=new long[ItemBalance.ComponentIds.Length];public long Fragments,ResearchFragments;public long[] Hardware=new long[Balance.Hardware.Length];public double Elapsed,Credited,Discarded,From,Through;public ScientificNumber Credits=ScientificNumber.Zero,Data=ScientificNumber.Zero,Insight=ScientificNumber.Zero;
 }
 [Serializable]public sealed class ReturnReceipt
 {
  public ItemInstance[] items=Array.Empty<ItemInstance>();public long fragments,researchFragments;public long[] components=new long[ItemBalance.ComponentIds.Length];public int schema=1;public bool initialized=true,hasReport,read;public long id;public string context="main";public double from,through,elapsed,credited,discarded;public NumberData credits=ScientificNumber.Zero.ToData(),data=ScientificNumber.Zero.ToData(),insight=ScientificNumber.Zero.ToData(),availableCredits=ScientificNumber.Zero.ToData(),availableData=ScientificNumber.Zero.ToData();public double training,research,analyses,crafted;public long prestiges,axioms;public long[] hardware=new long[Balance.Hardware.Length];
  public ReturnReceipt Copy(){var n=(ReturnReceipt)MemberwiseClone();n.components=(long[])components.Clone();n.items=items.Select(x=>x.Copy()).ToArray();n.hardware=(long[])hardware.Clone();foreach(var field in typeof(ReturnReceipt).GetFields().Where(f=>f.FieldType==typeof(NumberData)))field.SetValue(n,ScientificNumber.FromData((NumberData)field.GetValue(this)).ToData());return n;}
  public static void Attach(GameState before,GameState after,AdvanceCapture c){if(c.Elapsed<=0)return;after.Return=new ReturnReceipt{items=after.Workshop.inventory.Where(item=>!before.Workshop.inventory.Any(old=>old.id==item.id)).Select(item=>item.Copy()).ToArray(),fragments=c.Fragments,researchFragments=c.ResearchFragments,components=(long[])c.Components.Clone(),hasReport=true,id=before.Return.id+1,context=ChallengeRules.Active(after)?"challenge":"main",from=c.From,through=c.Through,elapsed=c.Elapsed,credited=c.Credited,discarded=c.Discarded,credits=c.Credits.ToData(),data=c.Data.ToData(),insight=c.Insight.ToData(),availableCredits=after.Credits.ToData(),availableData=after.Data.ToData(),training=after.Lifetime.trainingCompleted-before.Lifetime.trainingCompleted,research=after.Lifetime.researchCompleted-before.Lifetime.researchCompleted,analyses=after.Lifetime.analysesCompleted-before.Lifetime.analysesCompleted,crafted=after.Lifetime.itemsCrafted-before.Lifetime.itemsCrafted,prestiges=after.Prestige.resets-before.Prestige.resets,axioms=after.Meta.resets-before.Meta.resets,hardware=(long[])c.Hardware.Clone()};after.Journal.returns=after.Journal.returns.Concat(new[]{after.Return.Copy()}).TakeLast(JournalCatalog.Recent).ToArray();LocalJournal.Record(after,"offline-return");}
  public static void Validate(ReturnReceipt r){if(r==null||!r.initialized||r.schema!=1||r.id<0||!new[]{"main","challenge"}.Contains(r.context)||r.items==null||r.components==null||r.components.Length!=ItemBalance.ComponentIds.Length||r.components.Any(x=>x<0)||r.fragments<0||r.researchFragments<0||r.hardware==null||r.hardware.Length!=Balance.Hardware.Length||r.hardware.Any(v=>v<0))throw new FormatException("Invalid return receipt");foreach(double v in new[]{r.from,r.through,r.elapsed,r.credited,r.discarded,r.training,r.research,r.analyses,r.crafted})if(!ScientificNumber.Finite(v)||v<0)throw new FormatException("Invalid return measurement");foreach(var n in new[]{r.credits,r.data,r.insight,r.availableCredits,r.availableData})ScientificNumber.FromData(n);}
 }
}
